    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0LC1RD_1RB1LC_1LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LC1RD_1RB1LC_1LA0RB = Some t ->
