    apply (fireo_1RB1LC_0LC1RD_1RB1LC_1LA0RB [SWin 2; SWinR 6; SCycL 2 0; SWin 6; SCycR 2; SWin 3] (StD, S0) ltac:(vm_compute; reflexivity)
