    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LC1RD_1RB1LC_1LA0RB [SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
