    rewrite (srun_sound tm false true chp_1RB1LC_1LA0RD_1LA____0LC0RD P0_1RB1LC_1LA0RD_1LA____0LC0RD P1_1RB1LC_1LA0RD_1LA____0LC0RD 4 8
