  - intros t Ht p _. apply fire_1RB1LC_1LA0RD_1LA____0LC0RD. exact Ht.
  - exact wit_1RB1LC_1LA0RD_1LA____0LC0RD.
  - apply qcleb_QC_22. reflexivity.
