Lemma lapi_1RB1LC_1LA1LC_1LB0RD_0LB1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
