    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_1LA1RA_1LA0RD_0LA1RD p j' E).
    + exact (geo_1RB1LC_1LA1RA_1LA0RD_0LA1RD p j' E).
    + lia.
