(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LC_1LA1RA_1LA0RD_0LA1RD : existsb (fun tg => cfires tm_1RB1LC_1LA1RA_1LA0RD_0LA1RD c0 34 tg) pins_1RB1LC_1LA1RA_1LA0RD_0LA1RD = true.
